<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),keyword=ref(''),statusFilter=ref(''),showModal=ref(false),error=ref(''),form=ref({Name:'',Phone:'',Email:'',IdentityNo:''});const filtered=computed(()=>items.value.filter(x=>(!statusFilter.value||x.Status===statusFilter.value)&&(!keyword.value||`${x.Name}${x.Phone}`.includes(keyword.value))));async function load(){items.value=(await api.get('/tenants',{params:{page:1,page_size:100}})).data.items||[]}async function add(){error.value='';try{await api.post('/tenants',form.value);showModal.value=false;form.value={Name:'',Phone:'',Email:'',IdentityNo:''};await load()}catch(e:any){error.value=e.response?.data?.error?.message||'新增租客失败'}}async function status(id:string,v:string){await api.patch(`/tenants/${id}/status`,{status:v});await load()}onMounted(load)</script><template><div class="page"><div class="page-title"><div><h1>租客档案</h1><p>维护承租人联系方式、证件信息和可签约状态</p></div><button class="primary-button" @click="showModal=true">＋ 新增租客</button></div><div class="stat-grid"><div class="stat-card"><span>全部租客</span><strong>{{items.length}}</strong></div><div class="stat-card"><span>可签约</span><strong>{{items.filter(x=>x.Status==='active').length}}</strong></div><div class="stat-card"><span>已停用</span><strong>{{items.filter(x=>x.Status==='disabled').length}}</strong></div><div class="stat-card"><span>资料完整</span><strong>{{items.filter(x=>x.Phone&&x.IdentityNo).length}}</strong></div></div><section class="card"><div class="toolbar"><div class="toolbar-left"><div class="field"><input class="search-input" v-model="keyword" placeholder="搜索姓名或电话"></div><div class="field"><select v-model="statusFilter"><option value="">全部状态</option><option value="active">可签约</option><option value="disabled">已停用</option></select></div></div><button class="secondary-button" @click="load">刷新</button></div><table v-if="filtered.length" class="data-table"><thead><tr><th>姓名</th><th>联系电话</th><th>邮箱</th><th>证件号</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.ID"><td><strong>{{x.Name}}</strong></td><td>{{x.Phone}}</td><td>{{x.Email||'-'}}</td><td>{{x.IdentityNo||'-'}}</td><td><span class="status-badge" :class="x.Status">{{x.Status==='active'?'可签约':'已停用'}}</span></td><td><div class="action-group"><button v-if="x.Status!=='active'" class="secondary-button" @click="status(x.ID,'active')">启用</button><button v-else class="danger-button" @click="status(x.ID,'disabled')">停用</button></div></td></tr></tbody></table><div v-else class="empty-state"><b>暂无租客档案</b><span>点击右上角新增第一位租客</span></div></section><div v-if="showModal" class="modal-mask" @click.self="showModal=false"><div class="modal"><div class="modal-header"><div><h3>新增租客</h3><small>租客启用后可用于创建租约</small></div><button class="close-button" @click="showModal=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>姓名 *</span><input v-model="form.Name" placeholder="请输入真实姓名"></label><label><span>联系电话 *</span><input v-model="form.Phone" placeholder="请输入手机号"></label><label><span>邮箱</span><input v-model="form.Email" type="email" placeholder="tenant@example.com"></label><label><span>证件号码</span><input v-model="form.IdentityNo" placeholder="身份证或其他证件号"></label></div><p v-if="error" class="form-error">{{error}}</p></div><div class="modal-footer"><button class="secondary-button" @click="showModal=false">取消</button><button class="primary-button" :disabled="!form.Name||!form.Phone" @click="add">确认新增</button></div></div></div></div></template>